{
  "schema_version": "sections_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "sections": [
        {
          "section_id": 1,
          "title": "The Final Five O'Clock",
          "intent": "Establish Artie's mundane life and the catastrophic accident that triggers the transition.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Artie's physical body is destroyed in a freak server-room collapse."
        },
        {
          "section_id": 2,
          "title": "Buffer Overflow",
          "intent": "Depict the character creation suite glitching as Artie's consciousness attempts to load.",
          "section_role": "build",
          "target_scene_count": 3,
          "end_condition": "Artie triggers a recursive logic loop in the stat allocation menu."
        },
        {
          "section_id": 3,
          "title": "The Spawn Point Error",
          "intent": "Artie finalizes his 'corrupted' build and enters the game world.",
          "section_role": "payoff",
          "target_scene_count": 3,
          "end_condition": "Artie spawns into the tutorial zone with a stat sheet that shouldn't exist."
        }
      ]
    },
    {
      "chapter_id": 2,
      "sections": [
        {
          "section_id": 1,
          "title": "Quest Log Exploits",
          "intent": "Artie identifies the first major flaw in the tutorial's quest-completion logic.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie identifies a repeatable quest that fails to check for completion flags."
        },
        {
          "section_id": 2,
          "title": "Compounding Interest",
          "intent": "Artie grinds the exploit to stack illegal reward multipliers.",
          "section_role": "build",
          "target_scene_count": 4,
          "end_condition": "Artie achieves a x1000 reward multiplier on a hidden tutorial achievement."
        },
        {
          "section_id": 3,
          "title": "The Golden Handshake",
          "intent": "Artie collects the massive payout and prepares to leave the starting zone.",
          "section_role": "payoff",
          "target_scene_count": 3,
          "end_condition": "Artie exits the tutorial zone carrying a legendary-tier inventory item."
        }
      ]
    },
    {
      "chapter_id": 3,
      "sections": [
        {
          "section_id": 1,
          "title": "Stop Right There",
          "intent": "The local authorities attempt to process Artie's anomalous presence.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie is cornered by the scripted Guard Captain for unauthorized entry."
        },
        {
          "section_id": 2,
          "title": "Collision Detection",
          "intent": "Artie uses tutorial-tier items to break the local physics engine.",
          "section_role": "build",
          "target_scene_count": 3,
          "end_condition": "Artie creates a physics-based feedback loop using three stackable boxes."
        },
        {
          "section_id": 3,
          "title": "The Sky-High Captain",
          "intent": "The confrontation concludes with a spectacular system failure.",
          "section_role": "payoff",
          "target_scene_count": 3,
          "end_condition": "The Guard Captain is launched into the stratosphere by a collision bug."
        }
      ]
    },
    {
      "chapter_id": 4,
      "sections": [
        {
          "section_id": 1,
          "title": "The Blue Screen of Death",
          "intent": "The System deploys Sentinels to investigate the physics anomaly.",
          "section_role": "setup",
          "target_scene_count": 4,
          "end_condition": "Artie escapes the first Sentinel by jumping into an unrendered map sector."
        },
        {
          "section_id": 2,
          "title": "The Asset Graveyard",
          "intent": "Artie navigates the 'Dead-Zone' where the game's UI and tracking fail.",
          "section_role": "build",
          "target_scene_count": 4,
          "end_condition": "Artie finds a fragment of 'Legacy Code' hidden in a deleted asset."
        },
        {
          "section_id": 3,
          "title": "Stealth Mode",
          "intent": "Artie integrates the code to hide from the System's active scanning.",
          "section_role": "payoff",
          "target_scene_count": 3,
          "end_condition": "Artie successfully masks his signature from the System's tracking UI."
        }
      ]
    },
    {
      "chapter_id": 5,
      "sections": [
        {
          "section_id": 1,
          "title": "Backdoor Entry",
          "intent": "Artie locates a high-level dungeon and finds a way to bypass its requirements.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie clips through the dungeon's terrain to bypass the level-gate."
        },
        {
          "section_id": 2,
          "title": "Pathfinding Errors",
          "intent": "Artie tackles the dungeon boss by exploiting its AI limitations.",
          "section_role": "build",
          "target_scene_count": 4,
          "end_condition": "Artie traps the corrupted guardian in an infinite pathfinding loop."
        },
        {
          "section_id": 3,
          "title": "The Null Pointer",
          "intent": "Artie reaches the final loot chest and claims his prize.",
          "section_role": "payoff",
          "target_scene_count": 3,
          "end_condition": "Artie retrieves the 'Null-Pointer Blade' from the corrupted chest."
        }
      ]
    },
    {
      "chapter_id": 6,
      "sections": [
        {
          "section_id": 1,
          "title": "Zone Lockdown",
          "intent": "The Regional Administrator forces a direct confrontation to delete Artie.",
          "section_role": "setup",
          "target_scene_count": 4,
          "end_condition": "The Administrator locks the zone, preventing any escape or clipping."
        },
        {
          "section_id": 2,
          "title": "Logic Bomb",
          "intent": "Artie uses his glitched items to fight a superior opponent.",
          "section_role": "build",
          "target_scene_count": 4,
          "end_condition": "Artie connects the Null-Pointer Blade to the boss's core logic stream."
        },
        {
          "section_id": 3,
          "title": "Fatal Exception",
          "intent": "The boss battle concludes by breaking the game's stability.",
          "section_role": "payoff",
          "target_scene_count": 4,
          "end_condition": "The boss crashes, triggering a system-wide emergency maintenance warning."
        }
      ]
    },
    {
      "chapter_id": 7,
      "sections": [
        {
          "section_id": 1,
          "title": "The Countdown",
          "intent": "Artie races to secure his position before the server patches him out.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie reaches the world-anchor before the maintenance timer hits zero."
        },
        {
          "section_id": 2,
          "title": "Hard-Coding Reality",
          "intent": "Artie attempts to write himself permanently into the world's architecture.",
          "section_role": "build",
          "target_scene_count": 4,
          "end_condition": "Artie successfully injects a 'ignore_all_updates' flag into the local zone."
        },
        {
          "section_id": 3,
          "title": "Patch Day",
          "intent": "The world updates, but Artie remains as a permanent resident.",
          "section_role": "payoff",
          "target_scene_count": 3,
          "end_condition": "Artie settles into his glitched sanctuary as the server comes back online."
        }
      ]
    }
  ]
}

